{"path":"ayid/index.html","content":"<!DOCTYPE html>
<html lang="id">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Landing Page</title>
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }
        body {
            font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
            line-height: 1.6;
            color: #333;
        }
        header {
            background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
            color: white;
            padding: 4rem 2rem;
            text-align: center;
        }
        header h1 {
            font-size: 3rem;
            margin-bottom: 1rem;
        }
        header p {
            font-size: 1.25rem;
            opacity: 0.95;
        }
        .container {
            max-width: 1200px;
            margin: 0 auto;
            padding: 3rem 2rem;
        }
        .features {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
            gap: 2rem;
            margin-top: 2rem;
        }
        .feature {
            padding: 2rem;
            background: #f8f9fa;
            border-radius: 8px;
            transition: transform 0.3s ease;
        }
        .feature:hover {
            transform: translateY(-5px);
        }
        .feature h3 {
            color: #667eea;
            margin-bottom: 1rem;
        }
        footer {
            background: #2d3748;
            color: white;
            text-align: center;
            padding: 2rem;
            margin-top: 3rem;
        }
    </style>
</head>
<body>
    <header>
        <h1>Selamat Datang</h1>
        <p>Landing page sederhana dan modern</p>
    </header>

    <div class="container">
        <h2>Fitur Utama</h2>
        <div class="features">
            <div class="feature">
                <h3>Desain Modern</h3>
                <p>Tampilan bersih dan profesional dengan gradient yang menarik</p>
            </div>
            <div class="feature">
                <h3>Responsif</h3>
                <p>Bekerja sempurna di semua ukuran layar dan perangkat</p>
            </div>
            <div class="feature">
                <h3>Cepat</h3>
                <p>HTML murni tanpa dependensi, loading instan</p>
            </div>
        </div>
    </div>

    <footer>
        <p>&copy; 2026 Landing Page. All rights reserved.</p>
    </footer>
</body>
</html>
"}
